function getSynthesiaTranslation(key, lang) {
    if (synthesiaTranslations[lang] && synthesiaTranslations[lang][key]) {
        return synthesiaTranslations[lang][key];
    }
    // Fallback à l'anglais
    if (synthesiaTranslations.en && synthesiaTranslations.en[key]) {
        return synthesiaTranslations.en[key];
    }
    return null;
}

// Appliquer les traductions synthesia
function applySynthesiaTranslations(lang) {
    console.log('🔥 Applying synthesia translations for:', lang);

    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');

        // Seulement pour les clés synthesia
        if (key && (key.startsWith('review.synthesia.') || key.startsWith('review.common.'))) {
            const translation = getSynthesiaTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });

    console.log(`✅ Applied ${count} synthesia translations`);
}

// Auto-appliquer quand la langue change
window.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applySynthesiaTranslations(lang), 200);
});

// Appliquer au chargement
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applySynthesiaTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applySynthesiaTranslations(currentLang);
}

console.log('✅ synthesia i18n loaded');
